formulas.expression:
/*
This formula will traverse the Account hierarchy from (including) current record all the way to the top (up to 6 levels) and will display the Name of the parent Account where IM_HIerarchy_Level__c field is "IM Group (IMGA)".
If there is no such level parent in the hierarchy - will leave field blank
*/

/* If No Parent AND this Record Hierarchy level IS NOT IMGA leave blank */
IF (LEN({!$Record.Account.ParentId})==0 && TEXT( {!$Record.Account.IM_Hierarchy_Level__c})!='IM Group (IMGA)', '',

/*Else If No Parent AND this Record Hierarchy level IS IMGA leave blank*/
IF (LEN({!$Record.Account.ParentId})==0 && TEXT( {!$Record.Account.IM_Hierarchy_Level__c})=='IM Group (IMGA)', '',


/*Else If parent is IMGA-Level, get name from parent*/
IF(TEXT( {!$Record.Account.Parent.IM_Hierarchy_Level__c} )=='IM Group (IMGA)', {!$Record.Account.Parent.Id},

/*Else If second parent is IMGA-Level, get name from second parent*/
IF(TEXT( {!$Record.Account.Parent.Parent.IM_Hierarchy_Level__c} )=='IM Group (IMGA)', {!$Record.Account.Parent.Parent.Id},

/*Else If third parent is IMGA-Level, get name from third parent*/
IF(TEXT( {!$Record.Account.Parent.Parent.Parent.IM_Hierarchy_Level__c} )=='IM Group (IMGA)', {!$Record.Account.Parent.Parent.Parent.Id},

/*Else If fourth parent is IMGA-Level, get name from fourth parent*/
IF(TEXT( {!$Record.Account.Parent.Parent.Parent.Parent.IM_Hierarchy_Level__c} )=='IM Group (IMGA)', {!$Record.Account.Parent.Parent.Parent.Parent.Id},

/*Else If fifth parent is IMGA-Level, get name from fifth parent*/
IF(TEXT( {!$Record.Account.Parent.Parent.Parent.Parent.Parent.IM_Hierarchy_Level__c} )=='IM Group (IMGA)',
{!$Record.Account.Parent.Parent.Parent.Parent.Parent.Id},

/*Else (when reached up six levels, if no IMGA-level parent found - then put blank.*/
'' )
)
)
)
)
)
)
